<?php
// ─── Database connection (SQLite) ───────────────────────────────────────────
define('DB_PATH', __DIR__ . '/data/flipkart.db');

function getDB(): PDO {
    static $pdo = null;
    if ($pdo === null) {
        if (!is_dir(__DIR__ . '/data')) {
            mkdir(__DIR__ . '/data', 0755, true);
        }
        $pdo = new PDO('sqlite:' . DB_PATH);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
        initDB($pdo);
    }
    return $pdo;
}

function initDB(PDO $pdo): void {
    $pdo->exec("PRAGMA journal_mode=WAL;");

    // Settings table (UPI ID, merchant name, etc.)
    $pdo->exec("CREATE TABLE IF NOT EXISTS settings (
        key   TEXT PRIMARY KEY,
        value TEXT NOT NULL
    )");

    // Products table
    $pdo->exec("CREATE TABLE IF NOT EXISTS products (
        id            TEXT PRIMARY KEY,
        name          TEXT NOT NULL,
        color         TEXT NOT NULL DEFAULT 'N/A',
        storage       TEXT NOT NULL DEFAULT 'NA',
        selling_price TEXT NOT NULL,
        mrp           TEXT NOT NULL,
        img1          TEXT NOT NULL DEFAULT '',
        img2          TEXT NOT NULL DEFAULT '',
        img3          TEXT NOT NULL DEFAULT '',
        img4          TEXT NOT NULL DEFAULT '',
        sort_order    INTEGER NOT NULL DEFAULT 0,
        active        INTEGER NOT NULL DEFAULT 1,
        created_at    TEXT NOT NULL DEFAULT (datetime('now'))
    )");

    // Seed default UPI settings if not set
    $stmt = $pdo->prepare("INSERT OR IGNORE INTO settings (key, value) VALUES (?, ?)");
    $stmt->execute(['upi_id',        'merchant1069004.augp@aubank']);
    $stmt->execute(['merchant_name', 'MeeraTraders']);
    $stmt->execute(['admin_password','admin123']);

    // Seed products from hardcoded list if table is empty
    $count = $pdo->query("SELECT COUNT(*) FROM products")->fetchColumn();
    if ((int)$count === 0) {
        seedProducts($pdo);
    }
}

